const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const bundle=fs.readFileSync(path.join(__dirname,'../simulation-worker.js'),'utf8');
const entry=bundle.split('"./browser-entry.cjs":function(module,exports,require){')[1].split('}};const cache=')[0];
async function run(options,ack){const messages=[];const R={create:()=>({config:{},seconds:0,paused:false,workers:{workers:[],jobs:[],events:[]},animals:{manager:{residents:[],events:[]}},events:[]}),step:s=>{s.seconds+=86400;if(s.seconds===20*86400)s.paused=true},frame:s=>({seconds:s.seconds,animals:[]})};const modules={'./ranch.cjs':R,'./planner.cjs':{start(){}},'./workers.cjs':{},'./sim.cjs':{grow:()=>({valid:true,world:{}}),environment:()=>({w:{}})}};const context={self:{},require:id=>modules[id],crypto:{randomUUID:()=> 'test'},setTimeout:(fn)=>setTimeout(fn,1),clearTimeout,postMessage:m=>{messages.push(m);if(m.type==='day'&&ack)context.self.onmessage({data:{type:'day-rendered'}})}};vm.runInNewContext(entry,context);await context.self.onmessage({data:{seed:43,size:'small',sceneOnly:true,...options}});assert(!messages.some(m=>m.type==='error'));assert.equal(messages.at(-1).type,'result');assert.equal(messages.at(-1).run.duration,20*86400);return messages;}
test('older scene pages finish without a daily-preview acknowledgment',async()=>{const messages=await run({},false);assert.equal(messages.filter(m=>m.type==='day').length,0)});
test('new scene pages receive and acknowledge all twenty daily previews',async()=>{const messages=await run({dailyPreview:true},true);assert.equal(messages.filter(m=>m.type==='day').length,20)});
test('a missing preview acknowledgment cannot deadlock the worker',async()=>{const messages=await run({dailyPreview:true},false);assert.equal(messages.filter(m=>m.type==='day').length,20)});

